import{_ as t,o as a,c as i,a2 as n}from"./chunks/framework.Bg-Zxr5O.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/PRINT.md","filePath":"manual-en/PRINT.md","lastUpdated":1785684581000}'),o={name:"manual-en/PRINT.md"};function s(l,e,r,d,c,p){return a(),i("div",null,[...e[0]||(e[0]=[n(`<h3 id="_8-12-print" tabindex="-1">8.12 PRINT <a class="header-anchor" href="#_8-12-print" aria-label="Permalink to &quot;8.12 PRINT&quot;">​</a></h3><pre><code>PRINT
        [OUTFILE=’file_name’]
        [RECORDS=n_lines]
        [{NOTABLE,TABLE}]
        [ENCODING=’encoding’]
        [/[line_no] arg…]

arg takes one of the following forms:
        ’string’ [start]
        var_list start-end [type_spec]
        var_list (fortran_spec)
        var_list *
</code></pre><p>The <code>PRINT</code> transformation writes variable data to the listing file or an output file. <code>PRINT</code> is executed when a procedure causes the data to be read. Follow <code>PRINT</code> by <code>EXECUTE</code> to print variable data without invoking a procedure (see <a href="./EXECUTE">EXECUTE</a>).</p><p>All <code>PRINT</code> subcommands are optional. If no strings or variables are specified, <code>PRINT</code> outputs a single blank line.</p><p>The <code>OUTFILE</code> subcommand specifies the file to receive the output. The file may be a file name as a string or a file handle (see <a href="./File-Handles">File Handles</a>). If <code>OUTFILE</code> is not present then output is sent to PSPP’s output listing file. When <code>OUTFILE</code> is present, the output is written to file_name in a plain text format, with a space inserted at beginning of each output line, even lines that otherwise would be blank.</p><p>The <code>ENCODING</code> subcommand may only be used if the <code>OUTFILE</code> subcommand is also used. It specifies the character encoding of the file. See <a href="./INSERT">INSERT</a>, for information on supported encodings.</p><p>The <code>RECORDS</code> subcommand specifies the number of lines to be output. The number of lines may optionally be surrounded by parentheses.</p><p><code>TABLE</code> will cause the <code>PRINT</code> command to output a table to the listing file that describes what it will print to the output file. <code>NOTABLE</code>, the default, suppresses this output table.</p><p>Introduce the strings and variables to be printed with a slash (‘/’). Optionally, the slash may be followed by a number indicating which output line is specified. In the absence of this line number, the next line number is specified. Multiple lines may be specified using multiple slashes with the intended output for a line following its respective slash.</p><p>Literal strings may be printed. Specify the string itself. Optionally the string may be followed by a column number, specifying the column on the line where the string should start. Otherwise, the string is printed at the current position on the line.</p><p>Variables to be printed can be specified in the same ways as available for <code>DATA LIST FIXED</code> (see <a href="./DATA-LIST-FIXED">DATA LIST FIXED</a>). In addition, a variable list may be followed by an asterisk (‘*’), which indicates that the variables should be printed in their dictionary print formats, separated by spaces. A variable list followed by a slash or the end of command is interpreted in the same way.</p><p>If a FORTRAN type specification is used to move backwards on the current line, then text is written at that point on the line, the line is truncated to that length, although additional text being added will again extend the line to that length.</p>`,12)])])}const f=t(o,[["render",s]]);export{u as __pageData,f as default};
